// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistReconstruction.sol";

import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import "../../libraries/SSTORE2.sol";
import { StreamArtistPayloadStore } from "./StreamArtistPayloadStore.sol";

/// @notice Append-only evidence archive for the proposed artist-authority successor.
/// @dev This contract owns no semantic record or decision. It never authenticates an artist,
///      consumes replay, answers current/latest state, calls a semantic owner, or exposes a
///      mutable binding. Exact evidence must be joined to authoritative owner state elsewhere.
contract StreamArtistArchiveV2 is IStreamArtistArchiveV2, IStreamArtistPayloadArchive {
    bytes32 private constant _MARKER = keccak256("6529STREAM_ARTIST_ARCHIVE_V2");
    bytes32 private constant _BINDING_DOMAIN = keccak256("6529STREAM_ARTIST_ARCHIVE_BINDING_V2");
    uint16 private constant _SCHEMA_VERSION = 2;

    struct EvidenceRecord {
        address pointer;
        uint32 payloadSize;
        uint64 appendedAtBlock;
        bytes32 contentHash;
    }

    address public immutable override artistRegistry;
    address public immutable override operationCoordinator;
    bytes32 public immutable override artistArchiveBindingHashV2;

    mapping(bytes32 evidenceId => mapping(uint64 evidenceVersion => EvidenceRecord)) private
        _evidence;

    constructor(address artistRegistry_, address operationCoordinator_) {
        if (artistRegistry_ == address(0) || operationCoordinator_ == address(0)) {
            revert ArtistArchiveInvalidBinding(artistRegistry_, operationCoordinator_);
        }
        artistRegistry = artistRegistry_;
        operationCoordinator = operationCoordinator_;
        artistArchiveBindingHashV2 = keccak256(
            abi.encode(
                _BINDING_DOMAIN,
                block.chainid,
                artistRegistry_,
                operationCoordinator_,
                type(IStreamArtistArchiveV2).interfaceId,
                _MARKER,
                _SCHEMA_VERSION,
                SSTORE2.MAX_DATA_LENGTH
            )
        );
    }

    function supportsInterface(bytes4 interfaceId) external pure override(IERC165) returns (bool) {
        return interfaceId == type(IStreamArtistArchiveV2).interfaceId
            || interfaceId == type(IStreamArtistPayloadArchive).interfaceId
            || interfaceId == type(IStreamArtistReconstruction).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    function artistArchiveMarkerV2() external pure returns (bytes32) {
        return _MARKER;
    }

    function artistArchiveSchemaV2() external pure returns (uint16) {
        return _SCHEMA_VERSION;
    }

    function artistArchiveMaxEvidenceBytesV2() external pure returns (uint256) {
        return SSTORE2.MAX_DATA_LENGTH;
    }

    function appendArtistEvidenceV2(
        bytes32 evidenceId,
        uint64 evidenceVersion,
        bytes calldata evidence
    ) external returns (bytes32 contentHash, address pointer, bool appended) {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        _requireValidKey(evidenceId, evidenceVersion);
        uint256 payloadSize = evidence.length;
        if (payloadSize == 0) {
            revert ArtistArchiveEmptyEvidence(evidenceId, evidenceVersion);
        }
        if (payloadSize > SSTORE2.MAX_DATA_LENGTH) {
            revert ArtistArchiveEvidenceTooLarge(payloadSize, SSTORE2.MAX_DATA_LENGTH);
        }
        if (block.number > type(uint64).max) {
            revert ArtistArchiveBlockNumberOverflow(block.number);
        }

        contentHash = keccak256(evidence);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer != address(0)) {
            if (record.contentHash != contentHash || record.payloadSize != payloadSize) {
                revert ArtistArchiveEvidenceConflict(
                    evidenceId, evidenceVersion, record.contentHash, contentHash
                );
            }
            return (record.contentHash, record.pointer, false);
        }

        pointer = SSTORE2.write(evidence);
        record.pointer = pointer;
        // `payloadSize <= SSTORE2.MAX_DATA_LENGTH`, so this narrowing is exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.payloadSize = uint32(payloadSize);
        // The explicit bound above makes the frozen uint64 receipt field exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.appendedAtBlock = uint64(block.number);
        record.contentHash = contentHash;
        StreamArtistPayloadStore.registerPointer(
            pointer, keccak256("ARTIST_OPERATION_EVIDENCE"), contentHash
        );
        emit ArtistArchiveEvidenceAppendedV2(
            evidenceId, evidenceVersion, contentHash, pointer, payloadSize
        );
        return (contentHash, pointer, true);
    }

    function artistEvidenceMetadataV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes32 contentHash, address pointer, uint32 payloadSize, uint64 appendedAtBlock)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        return (record.contentHash, record.pointer, record.payloadSize, record.appendedAtBlock);
    }

    function artistEvidenceBytesV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes memory evidence)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        evidence = SSTORE2.read(record.pointer);
        bytes32 observedHash = keccak256(evidence);
        if (evidence.length != record.payloadSize || observedHash != record.contentHash) {
            revert ArtistArchiveEvidenceCorrupted(
                evidenceId, evidenceVersion, record.contentHash, observedHash
            );
        }
    }

    function registerArtistStoredPayload(address pointer, bytes32 kind, bytes32 hash)
        external
        override
    {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        StreamArtistPayloadStore.registerPointer(pointer, kind, hash);
    }

    function recordPreimageBytes(bytes32 hash) external view override returns (bytes memory) {
        return StreamArtistPayloadStore.recordBytes(hash);
    }

    function storedPayloadCount() external view override returns (uint256) {
        return StreamArtistPayloadStore.count();
    }

    function storedPayloadAt(uint256 index)
        external
        view
        override
        returns (address, bytes32, bytes32)
    {
        return StreamArtistPayloadStore.at(index);
    }

    function _requireValidKey(bytes32 evidenceId, uint64 evidenceVersion) private pure {
        if (evidenceId == bytes32(0) || evidenceVersion == 0) {
            revert ArtistArchiveInvalidEvidenceKey(evidenceId, evidenceVersion);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamArtistHashes } from "./StreamArtistHashes.sol";
import { StreamArtistRotationHashes } from "./StreamArtistRotationHashes.sol";
import {
    StreamArtistRecoveryStagingHistory as Stages
} from "./StreamArtistRecoveryStagingHistory.sol";
import { IStreamArtistOwner } from "../../interfaces/stream/artist/IStreamArtistOwner.sol";
import {
    IStreamArtistIdentityContestOwner
} from "../../interfaces/stream/artist/IStreamArtistIdentityContest.sol";
import {
    IStreamArtistIdentityDismissalOwner
} from "../../interfaces/stream/artist/IStreamArtistIdentityDismissal.sol";
import {
    IStreamArtistIdentityRecoveryOwner
} from "../../interfaces/stream/artist/IStreamArtistIdentityRecovery.sol";
import {
    IStreamArtistRotationReads
} from "../../interfaces/stream/artist/IStreamArtistRotation.sol";
import {
    IStreamArtistEstateOwner
} from "../../interfaces/stream/artist/IStreamArtistEstateOwner.sol";
import {
    StreamArtistIdentityContestTypes as C
} from "../../interfaces/stream/artist/StreamArtistIdentityContestTypes.sol";
import {
    StreamArtistIdentityDismissalTypes as D
} from "../../interfaces/stream/artist/StreamArtistIdentityDismissalTypes.sol";
import {
    StreamArtistRotationTypes as R
} from "../../interfaces/stream/artist/StreamArtistRotationTypes.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistIdentityRecoveryOperationTypes as Recovery
} from "../../interfaces/stream/artist/StreamArtistIdentityRecoveryOperationTypes.sol";

/// @notice Current original ACTIVE1 compromise facts after an admitted living recovery.
/// @dev The caller supplies its fixed owner and authenticates the current principal, executed
/// ancestry, maturity and any pending rotation's predecessor. This reader does not dismiss the
/// cause, synthesize a closure or replay historical authorization.
library StreamArtistCurrentCompromiseReads {
    struct Facts {
        C.Record contest;
        R.RotationRecord pending;
        bytes32 proof;
    }

    struct Environment {
        address owner;
        address registry;
        uint256 chainId;
    }

    function read(
        address owner,
        address registry,
        uint256 chainId,
        D.Cause memory current,
        R.TransitionState memory executed
    ) public view returns (Facts memory f) {
        bytes32 artistId = current.facts.artistId;
        if (
            owner.code.length == 0 || registry == address(0) || chainId != block.chainid
                || IStreamArtistOwner(owner).deploymentChainId() != chainId
                || IStreamArtistOwner(owner).artistRegistry() != registry
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(artistId);
        Environment memory e = Environment(owner, registry, chainId);
        bytes32 living = _living(e, artistId);
        _cause(e, current, executed);
        f.contest = IStreamArtistIdentityContestOwner(owner)
            .identityContestRecord(current.facts.referenceHash);
        bytes32 subject = _contest(e, current, f.contest);
        if (current.facts.pendingTransitionHash != 0) {
            f.pending = _pending(e, current, executed, f.contest);
        }
        f.proof = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_CURRENT_COMPROMISE_FACTS_V1"),
                chainId,
                registry,
                owner,
                living,
                current,
                executed,
                f.contest,
                f.pending,
                subject
            )
        );
    }

    /// @notice Read an original current compromise or standing veto for living or estate recovery.
    /// @dev The caller authenticates the first/repeated recovery profile, actual authority origin,
    /// ancestry and maturity. Only living authority may have no executed predecessor. Standing
    /// vetoes retain an empty Contest: their original cause and rotation-veto replay are the proof.
    function readFamily(
        address owner,
        address registry,
        uint256 chainId,
        D.Cause memory current,
        R.TransitionState memory executed
    ) public view returns (Facts memory f) {
        return _readFamily(owner, registry, chainId, current, executed, true, false);
    }

    /// @notice Original cause consumed by a caller-authenticated admitted operation35.
    /// @dev The caller must prove that recovery's native consumption replay. No live head is
    /// substituted for the original captured execution or pending transition.
    function readConsumed(
        address owner,
        address registry,
        uint256 chainId,
        D.Cause memory current,
        R.TransitionState memory executed
    ) public view returns (Facts memory f) {
        return _readFamily(owner, registry, chainId, current, executed, false, false);
    }

    /// @dev The fixed notice reader separately authenticates the original phase1/2 lifecycle.
    function readNotice(
        address owner,
        address registry,
        uint256 chainId,
        D.Cause memory current,
        R.TransitionState memory executed
    ) public view returns (Facts memory) {
        return _readFamily(owner, registry, chainId, current, executed, true, true);
    }

    /// @dev The caller also proves the original35 consumption and notice cancellation.
    function readConsumedNotice(
        address owner,
        address registry,
        uint256 chainId,
        D.Cause memory current,
        R.TransitionState memory executed
    ) public view returns (Facts memory) {
        return _readFamily(owner, registry, chainId, current, executed, false, true);
    }

    function _readFamily(
        address owner,
        address registry,
        uint256 chainId,
        D.Cause memory current,
        R.TransitionState memory executed,
        bool live,
        bool notice
    ) private view returns (Facts memory f) {
        bytes32 artistId = current.facts.artistId;
        if (
            owner.code.length == 0 || registry == address(0) || chainId != block.chainid
                || IStreamArtistOwner(owner).deploymentChainId() != chainId
                || IStreamArtistOwner(owner).artistRegistry() != registry
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(artistId);
        Environment memory e = Environment(owner, registry, chainId);
        _familyCause(e, current, executed, live, notice);
        bytes32 subject;
        bytes32 standing;
        bytes32 estateProof;
        if (current.facts.kind == 1) {
            f.contest = IStreamArtistIdentityContestOwner(owner)
                .identityContestRecord(current.facts.referenceHash);
            subject =
                _contestClass(e, current, f.contest, notice ? 2 : current.facts.authorityClass);
        } else {
            standing = _standing(e, current);
        }
        if (current.facts.pendingTransitionHash != 0) {
            if (
                IStreamArtistRotationReads(owner)
                    .rotationRecord(current.facts.pendingTransitionHash)
                    .recordHash != 0
            ) {
                f.pending = _pendingRecord(
                    e, current, executed, f.contest, current.facts.kind == 1, live
                );
            } else {
                estateProof = _pendingEstate(e, current, executed, f.contest, live);
            }
        }
        f.proof = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_CURRENT_CAUSE_FAMILY_FACTS_V1"),
                chainId,
                registry,
                owner,
                current,
                executed,
                f.contest,
                f.pending,
                subject,
                standing
            )
        );
        // Only this new estate profile adds a wrapper. Existing family and original read()
        // commitments retain their exact original encoding; S is never a RotationRecord.
        if (estateProof != 0) {
            f.proof = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_CURRENT_ESTATE_COMPROMISE_FACTS_V1"),
                    f.proof,
                    estateProof
                )
            );
        }
        if (notice) {
            f.proof = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_CURRENT_NOTICE_COMPROMISE_FACTS_V1"), f.proof
                )
            );
        }
    }

    function _pendingEstate(
        Environment memory e,
        D.Cause memory current,
        R.TransitionState memory executed,
        C.Record memory contest,
        bool live
    ) private view returns (bytes32) {
        bytes32 artistId = current.facts.artistId;
        bytes32 hash = current.facts.pendingTransitionHash;
        if (current.facts.kind != 1 || current.facts.authorityClass != 1 || hash == 0) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(artistId);
        }
        uint64 revision = Stages.compromiseRevision(
            e.owner, e.registry, e.chainId, artistId, contest.recordHash
        );
        Stages.EstateFacts memory estate =
            Stages.cancelledEstate(e.owner, e.registry, e.chainId, artistId, hash, revision);
        (address successor, uint64 noticeEndsAt, bytes32 activation) =
            IStreamArtistEstateOwner(e.owner).estateActivationState(artistId);
        (address old_, address new_, uint64 ends, uint32 approvals, bytes32 pending) =
            IStreamArtistRotationReads(e.owner).pendingRotation(artistId);
        D.Closure memory closed =
            IStreamArtistIdentityDismissalOwner(e.owner).identityTransitionClosure(artistId, hash);
        D.Closure memory emptyClosure;
        R.RotationRecord memory emptyRotation;
        if (
            hash == executed.recordHash
                || (live
                    && IStreamArtistRotationReads(e.owner).lastArtistTransition(artistId) != hash)
                || estate.request.incumbent != current.facts.incumbent
                || estate.request.requestedAt < executed.executedAt
                || estate.request.requestedAt > current.facts.enteredAt
                || estate.transition.contestedAt != current.facts.enteredAt
                || estate.cancellationReplay.touchedRevision != revision
                || contest.capturedGuardianSetRecordHash != estate.request.guardianRecordHash
                || (live
                    && (successor != address(0)
                        || noticeEndsAt != 0
                        || activation != 0
                        || old_ != address(0)
                        || new_ != address(0)
                        || ends != 0
                        || approvals != 0
                        || pending != 0))
                || keccak256(abi.encode(closed)) != keccak256(abi.encode(emptyClosure))
                || keccak256(abi.encode(IStreamArtistRotationReads(e.owner).rotationRecord(hash)))
                    != keccak256(abi.encode(emptyRotation))
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(artistId);
        return keccak256(abi.encode(estate.proof, revision, closed));
    }

    function _familyCause(
        Environment memory e,
        D.Cause memory current,
        R.TransitionState memory executed,
        bool live,
        bool notice
    ) private view {
        D.CauseFacts memory c = current.facts;
        if (
            c.artistId == 0 || current.causeHash == 0 || (c.kind != 1 && c.kind != 2)
                || (c.authorityClass != 1 && c.authorityClass != 3)
                || (notice
                        ? c.kind != 1 || c.authorityClass != 1 || c.priorStatus != 2
                        || c.pendingTransitionHash != 0
                        : c.priorStatus != c.authorityClass) || c.incumbent == address(0)
                || c.actor == address(0) || c.referenceHash == 0
                || (c.kind == 1
                        ? c.evidenceHash == 0 || c.reasonHash == 0
                        : c.evidenceHash != 0 || c.referenceHash != c.pendingTransitionHash)
                || c.enteredAt == 0 || c.enteredAt > block.timestamp
                || c.executedTransitionHash != executed.recordHash
                || current.causeHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_IDENTITY_CONTEST_CAUSE_V1"),
                            e.chainId,
                            e.registry,
                            e.owner,
                            c
                        )
                    )
                || (live
                    && keccak256(abi.encode(current))
                        != keccak256(
                            abi.encode(
                                IStreamArtistIdentityDismissalOwner(e.owner)
                                    .currentIdentityContestCause(c.artistId)
                            )
                        ))
                || keccak256(abi.encode(current))
                    != keccak256(
                        abi.encode(
                            IStreamArtistIdentityDismissalOwner(e.owner)
                                .identityContestCause(current.causeHash)
                        )
                    )
                || keccak256(abi.encode(executed))
                    != keccak256(
                        abi.encode(
                            IStreamArtistRotationReads(e.owner)
                                .artistTransitionState(executed.recordHash)
                        )
                    )
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(c.artistId);
        if (executed.recordHash == 0) {
            R.TransitionState memory empty;
            if (
                c.authorityClass != 1
                    || keccak256(abi.encode(executed)) != keccak256(abi.encode(empty))
            ) {
                revert Recovery.UnsupportedIdentityRecoveryProfile(c.artistId);
            }
        } else if (
            executed.artistId != c.artistId || executed.phase != 2 || executed.executedAt == 0
                || executed.executedAt > c.enteredAt
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(c.artistId);
        }
    }

    function _standing(Environment memory e, D.Cause memory current)
        private
        view
        returns (bytes32)
    {
        IStreamArtistOwner owner = IStreamArtistOwner(e.owner);
        bytes32 key = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                e.chainId,
                e.registry,
                owner.operationCoordinator(),
                owner.archiveV2(),
                e.owner,
                owner.domainId(),
                keccak256("identity_authority.replay.rotation_veto_key"),
                current.facts.pendingTransitionHash
            )
        );
        T.ReplayCell memory cell = owner.replayCell(key);
        if (
            cell.commitment != current.facts.pendingTransitionHash || cell.kind != 1
                || cell.status != 2 || cell.touchedRevision == 0
                || cell.touchedRevision > owner.ownerStateSnapshotV2().revision
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
        // The fixed-owner canonical Cause authenticates the original actor and optional reason.
        // The veto key commits P, not an independently stored Contest or a fresh role decision.
        return keccak256(abi.encode(key, cell));
    }

    function _living(Environment memory e, bytes32 artistId) private view returns (bytes32 hash) {
        hash = IStreamArtistIdentityRecoveryOwner(e.owner).latestIdentityRecovery(artistId);
        Recovery.Record memory prior =
            IStreamArtistIdentityRecoveryOwner(e.owner).identityRecoveryRecord(hash);
        if (
            hash == 0 || prior.recordHash != hash || prior.fields.artistId != artistId
                || prior.fields.vestedAuthorityClass != 1
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(artistId);
    }

    function _cause(Environment memory e, D.Cause memory current, R.TransitionState memory executed)
        private
        view
    {
        D.CauseFacts memory c = current.facts;
        if (
            c.artistId == 0 || current.causeHash == 0 || c.kind != 1 || c.authorityClass != 1
                || c.priorStatus != 1 || c.incumbent == address(0) || c.actor == address(0)
                || c.referenceHash == 0 || c.evidenceHash == 0 || c.reasonHash == 0
                || c.enteredAt == 0 || c.enteredAt > block.timestamp || executed.recordHash == 0
                || executed.artistId != c.artistId || executed.phase != 2
                || executed.executedAt == 0 || executed.executedAt > c.enteredAt
                || c.executedTransitionHash != executed.recordHash
                || current.causeHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_IDENTITY_CONTEST_CAUSE_V1"),
                            e.chainId,
                            e.registry,
                            e.owner,
                            c
                        )
                    )
                || keccak256(abi.encode(current))
                    != keccak256(
                        abi.encode(
                            IStreamArtistIdentityDismissalOwner(e.owner)
                                .currentIdentityContestCause(c.artistId)
                        )
                    )
                || keccak256(abi.encode(current))
                    != keccak256(
                        abi.encode(
                            IStreamArtistIdentityDismissalOwner(e.owner)
                                .identityContestCause(current.causeHash)
                        )
                    )
                || keccak256(abi.encode(executed))
                    != keccak256(
                        abi.encode(
                            IStreamArtistRotationReads(e.owner)
                                .artistTransitionState(executed.recordHash)
                        )
                    )
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(c.artistId);
    }

    function _contest(Environment memory e, D.Cause memory current, C.Record memory c)
        private
        view
        returns (bytes32)
    {
        return _contestClass(e, current, c, 1);
    }

    function _contestClass(
        Environment memory e,
        D.Cause memory current,
        C.Record memory c,
        uint8 authorityClass
    ) private view returns (bytes32) {
        D.CauseFacts memory f = current.facts;
        if (
            c.recordHash != f.referenceHash || c.terms.artistId != f.artistId
                || c.terms.evidenceHash != f.evidenceHash || c.terms.reasonHash != f.reasonHash
                || c.contester != f.actor || c.contestedAt != f.enteredAt
                || c.priorStatus != authorityClass
                || c.pendingTransitionRecordHash != f.pendingTransitionHash
                || c.executedTransitionRecordHash != f.executedTransitionHash
                || c.recordHash
                    != keccak256(
                        abi.encode(
                            bytes32(
                                0x26a4221cd1625ab88b1ac279e1708a73efa176e486242b26832cdc94fe25e6bb
                            ),
                            e.chainId,
                            e.registry,
                            c.terms.artistId,
                            c.contester,
                            c.terms.subjectRecordHash,
                            c.terms.evidenceHash,
                            c.terms.reasonHash,
                            c.contestedAt
                        )
                    )
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(f.artistId);
        if (c.terms.subjectRecordHash == 0) return 0;
        R.TransitionState memory subject =
            IStreamArtistRotationReads(e.owner).artistTransitionState(c.terms.subjectRecordHash);
        if (
            subject.recordHash != c.terms.subjectRecordHash || subject.artistId != f.artistId
                || (subject.phase != 2 && subject.phase != 3) || subject.stagedAt == 0
                || subject.stagedAt > f.enteredAt
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(f.artistId);
        return _subject(e, current, subject);
    }

    function _subject(
        Environment memory e,
        D.Cause memory current,
        R.TransitionState memory subject
    ) private view returns (bytes32) {
        R.RotationRecord memory rotation = IStreamArtistRotationReads(e.owner)
            .rotationRecord(subject.recordHash);
        if (rotation.recordHash != subject.recordHash) {
            Recovery.Record memory recovered = IStreamArtistIdentityRecoveryOwner(e.owner)
                .identityRecoveryRecord(subject.recordHash);
            // Other original transition kinds have their own marker writers.
            if (recovered.recordHash != subject.recordHash) return keccak256(abi.encode(subject));
        }
        if (subject.contestedAt > current.facts.enteredAt) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
        }
        D.Closure memory closed = IStreamArtistIdentityDismissalOwner(e.owner)
            .identityTransitionClosure(subject.artistId, subject.recordHash);
        D.Closure memory empty;
        if (keccak256(abi.encode(closed)) == keccak256(abi.encode(empty))) {
            if (subject.contestedAt == 0) {
                revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
            }
            return keccak256(abi.encode(subject, closed));
        }
        D.Record memory dismissal = IStreamArtistIdentityDismissalOwner(e.owner)
            .identityContestDismissalRecord(closed.dismissalRecordHash);
        uint64 ends = subject.phase == 2 ? subject.postWindowEndsAt : subject.contestEndsAt;
        bool abandoned = subject.phase == 3
            || (subject.phase == 2
                && subject.contestedAt != 0
                && subject.contestedAt < subject.postWindowEndsAt);
        if (
            closed.dismissalRecordHash == 0 || closed.artistId != subject.artistId
                || closed.transitionRecordHash != subject.recordHash || closed.windowEndsAt != ends
                || closed.contestedAt != subject.contestedAt || closed.abandoned != abandoned
                || dismissal.recordHash != closed.dismissalRecordHash
                || dismissal.terms.artistId != subject.artistId
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
        return keccak256(abi.encode(subject, closed, dismissal));
    }

    function _pending(
        Environment memory e,
        D.Cause memory current,
        R.TransitionState memory executed,
        C.Record memory contest
    ) private view returns (R.RotationRecord memory r) {
        return _pendingRecord(e, current, executed, contest, true, true);
    }

    function _pendingRecord(
        Environment memory e,
        D.Cause memory current,
        R.TransitionState memory executed,
        C.Record memory contest,
        bool hasContest,
        bool live
    ) private view returns (R.RotationRecord memory r) {
        bytes32 hash = current.facts.pendingTransitionHash;
        bytes32 artistId = current.facts.artistId;
        r = IStreamArtistRotationReads(e.owner).rotationRecord(hash);
        (address old_, address new_, uint64 ends, uint32 approvals, bytes32 pending) =
            IStreamArtistRotationReads(e.owner).pendingRotation(artistId);
        D.Closure memory closed =
            IStreamArtistIdentityDismissalOwner(e.owner).identityTransitionClosure(artistId, hash);
        D.Closure memory empty;
        StreamArtistHashes.Environment memory original;
        original.chainId = e.chainId;
        original.registry = e.registry;
        if (
            hash == executed.recordHash || r.recordHash != hash || r.terms.artistId != artistId
                || (live
                    && (IStreamArtistRotationReads(e.owner).lastArtistTransition(artistId) != hash
                        || old_ != address(0)
                        || new_ != address(0)
                        || ends != 0
                        || approvals != 0
                        || pending != 0)) || r.terms.oldAddress != current.facts.incumbent
                || r.terms.newAddress == address(0) || r.terms.oldAddress == r.terms.newAddress
                || r.transition.artistId != artistId || r.transition.recordHash != hash
                || r.transition.phase != 3 || r.transition.executedAt != 0
                || r.transition.postWindowEndsAt != 0 || r.transition.stagedAt == 0
                || r.transition.stagedAt < executed.executedAt
                || r.transition.stagedAt > current.facts.enteredAt
                || r.transition.contestedAt != current.facts.enteredAt
                || r.effectiveWindow < 72 hours || r.standingTail < 30 days || r.timingRevision == 0
                || uint256(r.transition.contestEndsAt)
                    != uint256(r.transition.stagedAt) + r.effectiveWindow
                || StreamArtistRotationHashes.rotationRecord(
                        original,
                        r.terms,
                        r.oldNonce,
                        r.transition.stagedAt,
                        r.transition.contestEndsAt
                    ) != hash
                || keccak256(abi.encode(r.transition))
                    != keccak256(
                        abi.encode(IStreamArtistRotationReads(e.owner).artistTransitionState(hash))
                    )
                || (hasContest && contest.capturedGuardianSetRecordHash != r.guardianSetRecordHash)
                || keccak256(abi.encode(closed)) != keccak256(abi.encode(empty))
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(artistId);
    }
}

