    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ACCEPTANCE_RECORD_V1"),
                e.chainId,
                e.registry,
                e.core,
                collectionId,
                b.generation,
                b.bindingHash,
                uint8(1),
                signer,
