            e,
            keccak256(
                abi.encode(
                    bytes32(0x87eea3b0d5e1275bbdc74e691b4e19a12e9e76b634bac03ae439ae584859ecd0),
                    p.artistId,
                    p.oldAddress,
                    p.newAddress,
                    a.nonce,
                    a.time
                )
            )
        );
